/bin/bash -lc "node --input-type=module <<'NODE'
import ts from 'typescript';
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const source = ts.transpileModule(fs.readFileSync('src/i18n.ts', 'utf8'), {compilerOptions: {module: ts.ModuleKind.CommonJS}}).outputText;
function load(saved, browserLanguage, blocked = false) {
  const storage = new Map(saved === null ? [] : [['app.language', saved]]);
  const context = {exports: {}, navigator: {language: browserLanguage}, window: {localStorage: {
    getItem(key) { if (blocked) throw new Error('Unavailable'); return storage.get(key) ?? null; },
    setItem(key, value) { if (blocked) throw new Error('Unavailable'); storage.set(key, value); },
  }}};
  vm.runInNewContext(source, context);
  return {api: context.exports, storage};
}
assert.equal(load('ru', 'en-US').api.getInitialLanguage(), 'ru');
assert.equal(load('en', 'ru-RU').api.getInitialLanguage(), 'en');
assert.equal(load(null, 'ru-RU').api.getInitialLanguage(), 'ru');
assert.equal(load('invalid', 'de-DE').api.getInitialLanguage(), 'en');
const {api, storage} = load(null, 'en-US');
assert.equal(api.saveLanguage('ru'), true);
assert.equal(storage.get('app.language'), 'ru');
assert.equal(api.getInitialLanguage(), 'ru');
assert.equal(api.saveLanguage('en'), true);
assert.equal(api.getInitialLanguage(), 'en');
const blocked = load(null, 'ru-RU', true).api;
assert.equal(blocked.getInitialLanguage(), 'ru');
assert.equal(blocked.saveLanguage('en'), false);
assert.deepEqual(Object.keys(api.translations.en), Object.keys(api.translations.ru));
console.log('Passed: saved preference, both switch directions, browser locale, invalid preference, unavailable storage, translation completeness.');
