/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {getInitialLanguage, saveLanguage, translations} from './src/i18n.ts';
function setup(saved, browserLanguage, blocked = false) {
  const storage = new Map(saved === null ? [] : [['app.language', saved]]);
  Object.defineProperty(globalThis, 'navigator', {value: {language: browserLanguage}, configurable: true});
  globalThis.window = {localStorage: {
    getItem(key) { if (blocked) throw new Error('Unavailable'); return storage.get(key) ?? null; },
    setItem(key, value) { if (blocked) throw new Error('Unavailable'); storage.set(key, value); },
  }};
  return storage;
}
setup('ru', 'en-US');
assert.equal(getInitialLanguage(), 'ru');
setup('en', 'ru-RU');
assert.equal(getInitialLanguage(), 'en');
setup(null, 'ru-RU');
assert.equal(getInitialLanguage(), 'ru');
setup('invalid', 'de-DE');
assert.equal(getInitialLanguage(), 'en');
const storage = setup(null, 'en-US');
assert.equal(saveLanguage('ru'), true);
assert.equal(storage.get('app.language'), 'ru');
assert.equal(getInitialLanguage(), 'ru');
assert.equal(saveLanguage('en'), true);
assert.equal(getInitialLanguage(), 'en');
setup(null, 'ru-RU', true);
assert.equal(getInitialLanguage(), 'ru');
assert.equal(saveLanguage('en'), false);
assert.deepEqual(Object.keys(translations.en), Object.keys(translations.ru));
console.log('Passed: saved preference, both switch directions, browser locale, invalid preference, unavailable storage, translation completeness.');
